// === Tab: sketch ===
// Code demostration for the workshop - Introduction to Creative Coding: Interactive Fireworks Party
// Echo Hui

let fireworks = [];
let soundFile = {
	fireworkInit: null,
	fireworkExplode: null,
}
let fireworksImg = [];

function preload(){
	soundFile.fireworkInit = loadSound("https://openprocessing.org/sketch/1538291/files/Firework-Whistle.mp3");
	soundFile.fireworkExplode = loadSound("https://openprocessing.org/sketch/1538291/files/Firework-Burst.mp3");
	fireworksImg[0] = loadImage("https://openprocessing.org/sketch/1538291/files/tears-of-joy-32.png");
	fireworksImg[1] = loadImage("https://openprocessing.org/sketch/1538291/files/skull-32.png");
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill(0);
	rect(0, 0, width, height);
	noStroke();
	// fireworks.push(new Firework({}));
}

function mousePressed() {
	// add a new firework
	fireworks.push(new Firework({
		sound: soundFile,
		mouse: true,
	}));
	fireworks[fireworks.length - 1].init(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

function draw() {
	fill(0, 20); // background with opacity
	rect(0, 0, width, height);

	if (random(1) < 0.02) { // 2% chance of adding a new firework
		// add a new firework
		fireworks.push(new Firework({ sound: soundFile }));
		fireworks[fireworks.length - 1].init();
	}

	// show the firework
	for (let i = fireworks.length - 1; i >= 0; i--) {
		fireworks[i].show();
		// remove extra fireworks
		if (fireworks[i].done()) {
			fireworks.splice(i, 1);
		}
	}
}

// === Tab: particle ===
// Individual particle
class Particle {
	constructor(args) {
		let def = {
			pos: createVector(0, 0),
			vel: createVector(random(2, -2), random(-15, -10)), // createVector(0, -10),
			acc: createVector(0, 0),
			gForce: createVector(0, 0.1), // gravitational force
			r: random(2, 8),
			seed: true, // determine if it is the seed firework particle
			lifespan: 1,
			color: color('#ffffff'),
			hue: 360,
			endColor: color('#ffffff'),
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	applyForce() {
		this.acc.add(this.gForce); // F = ma, here it simplifies to F = a * 1
	}

	update() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.acc.mult(0); // clears out the acceleration
	}

	show() {
		// displays the particle
		push();
			colorMode(HSB)
			translate(this.pos.x, this.pos.y);
			if (this.seed) {
				fill(this.color);
			} else {
				this.lifespan -= 0.005;
				fill(this.hue, 100, 100, this.lifespan);
			}

			circle(0,0,this.r);
		pop();

	}

	done() { 
		// check if the particle is faded out
		return this.lifespan <= 0 ? true : false;
	}
}

// === Tab: firework ===
// contains a particle, and the explosion of particles
class Firework {
	constructor(args) {
		var def = {
			// firework: new Particle({
			// 						pos: createVector(random(width), random(height - (height / 10), height)),
			// 					}),
			firework: null,
			sound: null,
			// array for storing explosion of particles
			particles: [], 
			particlesCount: 0,
			explodeStatus: false,
			// image file for mouse interaction
			mouse: false,
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	init(p) {
		if (!this.mouse) {
			this.firework = new Particle({
											pos: p || createVector(random(width), random(height - (height / 10), height)),
										});
		} else {
			this.firework = new EmojiParticle({
											pos: p || createVector(random(width), random(height - (height / 10), height)),
											r: random(25, 30),
										});
		}
		this.playSound('init');
	}

	playSound(str) {
		if(str === 'init') {
			this.sound.fireworkInit.setVolume(random(1) * random());
			this.sound.fireworkInit.play();
		} else if (str === 'explode') {
			this.sound.fireworkExplode.setVolume(random(1) * random());
			this.sound.fireworkExplode.play();
		}
	}

	done() { 
		// check if the particle exceeds the browser window
		return this.explodeStatus && this.particles.length === 0 ? true : false;
	}

	// check if the particle reaches the highest point
	checkExplodePoint() {
		if (this.firework.vel.y >=0) {
			this.explodeStatus = true;
			this.explode();
		}
	}

	// fireworks explosion
	explode() {
		this.particlesCount = random(100, 200);
		let baseHue = 180; // random(300);

		for( let i = 0; i < this.particlesCount; i++){
			let objParticle;
			if (!this.mouse) {
				let hue = random(0,120);
				let endHue = random(0,120);
				objParticle = new Particle({
					pos: createVector(this.firework.pos.x, this.firework.pos.y),
					vel: p5.Vector.random2D().mult(random(2, 5)),
					r: random(this.firework.r / 2, this.firework.r),
					seed: false,
					hue: baseHue + hue,
					// endColor: color( (120+ baseHue+ endHue)%360,360,360)
				})
			} else {
				objParticle = new EmojiParticle({
					pos: createVector(this.firework.pos.x, this.firework.pos.y),
					vel: p5.Vector.random2D().mult(random(2, 5)),
					r: random(this.firework.r / 2, this.firework.r),
					seed: false,
				})
			}

			this.particles.push(objParticle);
		}
		this.playSound('explode');
	}

	show() {
		push();
			// blendMode(SCREEN);
			colorMode(HSB);

			this.firework.applyForce();
			this.firework.update();

			// show the seed particle until it reaches the highest point
			if (!this.explodeStatus) {
				this.checkExplodePoint();
				this.firework.show();
			}

			// display fireworks explosion
			// for (let i = 0; i < this.particles.length; i++) {
			for (let i = this.particles.length - 1; i >= 0; i--) {
				this.particles[i].applyForce();
				this.particles[i].update();
				this.particles[i].show();

				// remove extra particles when it's faded out
				if (this.particles[i].done()) {
					this.particles.splice(i, 1);
				}
			}
		pop();
	}
}

// === Tab: emojiParticle ===
// Particle System Inheritance
class EmojiParticle extends Particle {
  constructor(pos, r) {
    super(pos, r);
  }

  show() {
    push();
			this.lifespan -= 0.005;
			imageMode(CENTER);
    	image(fireworksImg[1], this.pos.x, this.pos.y, this.r, this.r);
    pop();
  }
}

